import { cleanText, connKey, isIpv4, normalizeHost } from "@/lib/server-directory";

/**
 * Steam master-server list -> directory candidates. PURE parsing + a thin
 * fetcher; the database half is lib/directory-ingest/run.ts.
 *
 * Source: Steam Web API `IGameServersService/GetServerList` (needs a free Steam
 * Web API key in STEAM_WEB_API_KEY). Its terms for republishing the list on a
 * public directory are UNVERIFIED (growth item seo-026) — which is why nothing
 * here runs unless an admin turned ingestion on, and why the fetcher is only
 * ever called by scripts/directory-ingest.ts, never from a page render.
 *
 * Response rows (the documented fields we use): addr "ip:queryPort",
 * gameport, name, appid, gamedir, version, region, players, max_players, bots,
 * map, secure, dedicated, os, gametype (comma-separated tags). Anything else
 * is ignored; anything missing stays empty — nothing is invented.
 */

/** Families that register on the Steam master list, with their Steam app ids. */
export const VALVE_APPIDS: Record<string, number> = {
  valheim: 892970,
  projectzomboid: 108600,
  rust: 252490,
  cs2: 730,
  tf2: 440,
  gmod: 4000,
  l4d2: 550,
  ark: 346110,
  unturned: 304930,
  sdtd: 251570,
  conan: 440900,
};

export type ValveRaw = {
  addr?: string; gameport?: number; name?: string; appid?: number; version?: string;
  players?: number; max_players?: number; bots?: number; map?: string; dedicated?: boolean; gametype?: string;
};

export type ExternalCandidate = {
  source: "valve";
  sourceKey: string;
  game: string;
  name: string;
  host: string;
  ip: string;
  port: number;
  queryPort: number | null;
  map: string | null;
  players: number | null;
  maxPlayers: number | null;
  version: string | null;
  tags: string[];
  connKey: string;
  ipKey: string;
};

const num = (v: unknown): number | null => (typeof v === "number" && Number.isFinite(v) && v >= 0 ? Math.floor(v) : null);

/** Server names come from strangers: strip controls, collapse space, bound length, drop empties/links-only. */
export function cleanServerName(raw: unknown): string | null {
  const t = cleanText(raw, 80);
  if (!t || t.length < 3) return null;
  if (!/[\p{L}\p{N}]/u.test(t)) return null;
  return t;
}

export function parseValveRow(game: string, r: ValveRaw): ExternalCandidate | null {
  const m = /^(\d{1,3}(?:\.\d{1,3}){3}):(\d{1,5})$/.exec(String(r.addr ?? ""));
  if (!m) return null;
  const ip = normalizeHost(m[1]);
  if (!isIpv4(ip) || /^(0\.|10\.|127\.|169\.254\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)/.test(ip)) return null;
  const queryPort = Number(m[2]);
  // The join port is `gameport` when the row reports one; otherwise the address port.
  const port = num(r.gameport) && num(r.gameport)! > 0 && num(r.gameport)! < 65536 ? num(r.gameport)! : queryPort;
  if (!(port >= 1 && port <= 65535)) return null;
  const name = cleanServerName(r.name);
  if (!name) return null;
  if (r.dedicated === false) return null;
  const tags = String(r.gametype ?? "").split(",").map((t) => cleanText(t, 24)).filter((t): t is string => !!t).slice(0, 8);
  const key = connKey(game, ip, port);
  return {
    source: "valve", sourceKey: `${ip}:${port}`, game, name, host: ip, ip, port,
    queryPort: queryPort !== port ? queryPort : null,
    map: cleanText(r.map, 40), players: num(r.players), maxPlayers: num(r.max_players),
    version: cleanText(r.version, 24), tags, connKey: key, ipKey: key,
  };
}

export function parseValveResponse(game: string, json: unknown): ExternalCandidate[] {
  const rows = (json as { response?: { servers?: ValveRaw[] } } | null)?.response?.servers;
  if (!Array.isArray(rows)) return [];
  const seen = new Set<string>();
  const out: ExternalCandidate[] = [];
  for (const r of rows) {
    const c = parseValveRow(game, r);
    if (!c || seen.has(c.sourceKey)) continue;
    seen.add(c.sourceKey);
    out.push(c);
  }
  return out;
}

export class ValveFetchError extends Error {}

/** One bounded request. Throws ValveFetchError on anything but a clean 200 JSON body. */
export async function fetchValveList(game: string, opts: { key: string; limit?: number; timeoutMs?: number; fetchImpl?: typeof fetch }): Promise<ExternalCandidate[]> {
  const appid = VALVE_APPIDS[game];
  if (!appid) throw new ValveFetchError(`No Steam app id known for ${game}`);
  const limit = Math.min(Math.max(opts.limit ?? 1000, 1), 5000);
  // dedicated + at least one open slot is not required; empty servers are useful listings too.
  const filter = `\\appid\\${appid}\\dedicated\\1`;
  const url = `https://api.steampowered.com/IGameServersService/GetServerList/v1/?key=${encodeURIComponent(opts.key)}&limit=${limit}&filter=${encodeURIComponent(filter)}`;
  const ctl = new AbortController();
  const t = setTimeout(() => ctl.abort(), opts.timeoutMs ?? 25_000);
  try {
    const res = await (opts.fetchImpl ?? fetch)(url, { signal: ctl.signal, headers: { accept: "application/json" } });
    if (!res.ok) throw new ValveFetchError(`Steam list answered HTTP ${res.status}`);
    return parseValveResponse(game, await res.json());
  } catch (e) {
    if (e instanceof ValveFetchError) throw e;
    // never echo the URL (it carries the API key)
    throw new ValveFetchError(e instanceof Error && e.name === "AbortError" ? "Steam list timed out" : "Steam list request failed");
  } finally {
    clearTimeout(t);
  }
}
import { db } from "@/lib/db";
import { getSettingBool } from "@/lib/settings";
import { nxeonConnectionKeys } from "@/lib/server-directory-data";
import { loadRuleSet } from "@/lib/directory-blocklist-db";
import { evaluateHost, describeVerdict, type RuleSet } from "@/lib/directory-blocklist";
import { resolvePtrs, PTR_TTL_MS, type ReverseFn } from "./ptr";
import { isIpv4 } from "@/lib/server-directory";
import { fetchValveList, VALVE_APPIDS, ValveFetchError, type ExternalCandidate } from "./valve";

/**
 * Ingest one game from the Steam master list into ExternalServer. Gated:
 * `apply` writes only when Setting directory_ingest_enabled is true. Dry run
 * (default) fetches + counts and writes nothing.
 *
 * Dedupe at the door: a candidate whose connection (host:port or ip:port)
 * equals something Nxeon hosts is dropped — the directory shows OUR entry
 * (with the Nxeon badge), not a duplicate. Candidates already stored under the
 * same connKey from another source row are skipped too. Rows not seen for
 * PRUNE_AFTER_DAYS are deleted so a dead server does not linger.
 */
export const PRUNE_AFTER_DAYS = 3;

export type IngestResult = { game: string; fetched: number; inserted: number; updated: number; duplicates: number; pruned: number; blocked: number; dryRun: boolean };

export type PtrCache = Map<string, { ptrName: string | null; checkedAt: Date | null }>;
/** A found name is trusted 30 days; "no answer" only 1 day (a timeout must not stick). */
export function ptrFresh(c: { ptrName: string | null; checkedAt: Date | null } | undefined, now = Date.now()): boolean {
  if (!c?.checkedAt) return false;
  return now - c.checkedAt.getTime() < (c.ptrName ? PTR_TTL_MS : 86_400_000);
}

export type BlockVerdictRow<T> = { cand: T; ptrName: string | null; ptrCheckedAt: Date | null; blockedReason: string | null; blockedRule: string | null };

/**
 * Judge each candidate against the blocklist. Hostnames are judged directly;
 * IP-only candidates by their reverse-DNS name, taken from `cache` while fresh
 * and otherwise looked up here (bounded, see ptr.ts). Pure apart from `reverse`.
 */
export async function judgeCandidates<T extends { host: string; port: number }>(
  cands: T[], set: RuleSet, cache: PtrCache, opts: { reverse?: ReverseFn; now?: Date } = {},
): Promise<BlockVerdictRow<T>[]> {
  const now = opts.now ?? new Date();
  const isIp = (h: string) => isIpv4(h) || h.includes(":");
  const need = cands.filter((c) => isIp(c.host) && !ptrFresh(cache.get(c.host), now.getTime())).map((c) => c.host);
  const looked = need.length ? await resolvePtrs(need, { reverse: opts.reverse }) : new Map<string, string | null>();
  return cands.map((cand) => {
    let ptrName: string | null = null, ptrCheckedAt: Date | null = null;
    if (isIp(cand.host)) {
      if (looked.has(cand.host)) { ptrName = looked.get(cand.host) ?? null; ptrCheckedAt = now; }
      else { const c = cache.get(cand.host); ptrName = c?.ptrName ?? null; ptrCheckedAt = c?.checkedAt ?? null; }
    }
    const v = evaluateHost(cand.host, cand.port, set, { ptr: ptrName });
    return { cand, ptrName, ptrCheckedAt, blockedReason: describeVerdict(v), blockedRule: v.rule?.id ?? null };
  });
}

export function splitDuplicates<T extends { connKey: string; ipKey: string | null }>(cands: T[], nxeonKeys: Set<string>): { keep: T[]; dup: number } {
  const seen = new Set<string>();
  const keep: T[] = [];
  let dup = 0;
  for (const c of cands) {
    const keys = [c.connKey, ...(c.ipKey ? [c.ipKey] : [])];
    if (keys.some((k) => nxeonKeys.has(k) || seen.has(k))) { dup++; continue; }
    keys.forEach((k) => seen.add(k));
    keep.push(c);
  }
  return { keep, dup };
}

export async function ingestValveGame(game: string, opts: { apply: boolean; key: string; limit?: number; fetchImpl?: typeof fetch; reverse?: ReverseFn }): Promise<IngestResult> {
  if (!VALVE_APPIDS[game]) throw new Error(`Unsupported game for the Steam list: ${game}`);
  if (opts.apply && !(await getSettingBool("directory_ingest_enabled", false))) {
    throw new Error("Ingestion is switched off (Setting directory_ingest_enabled). Turn it on in /admin/directory first.");
  }
  const run = opts.apply ? await db.directoryIngestRun.create({ data: { source: "valve", game } }) : null;
  try {
    const fetched = await fetchValveList(game, { key: opts.key, limit: opts.limit, fetchImpl: opts.fetchImpl });
    const nxKeys = await nxeonConnectionKeys();
    const { keep, dup } = splitDuplicates<ExternalCandidate>(fetched, nxKeys);
    let inserted = 0, updated = 0, pruned = 0, blocked = 0;
    // Competitor-host blocklist. Blocked rows are STORED with a verdict (so admins can see what
    // was dropped and why, and re-evaluate when rules change) and filtered out of every display query.
    const { set } = await loadRuleSet();
    const existingRows = await db.externalServer.findMany({ where: { source: "valve", game }, select: { id: true, sourceKey: true, host: true, ptrName: true, ptrCheckedAt: true } });
    const cache: PtrCache = new Map(existingRows.map((r) => [r.host, { ptrName: r.ptrName, checkedAt: r.ptrCheckedAt }]));
    const judged = await judgeCandidates(keep, set, cache, { reverse: opts.reverse });
    blocked = judged.filter((j) => j.blockedReason).length;
    if (opts.apply) {
      const existing = new Map(existingRows.map((r) => [r.sourceKey, r.id]));
      const now = new Date();
      for (let i = 0; i < judged.length; i += 100) {
        await db.$transaction(judged.slice(i, i + 100).map(({ cand: c, ptrName, ptrCheckedAt, blockedReason, blockedRule }) => {
          const data = {
            blockedReason, blockedRule, ptrName, ptrCheckedAt,
            game: c.game, name: c.name, host: c.host, ip: c.ip, port: c.port, queryPort: c.queryPort, map: c.map,
            players: c.players, maxPlayers: c.maxPlayers, version: c.version, tags: c.tags,
            connKey: c.connKey, ipKey: c.ipKey, lastSeenAt: now,
          };
          if (existing.has(c.sourceKey)) updated++; else inserted++;
          return db.externalServer.upsert({
            where: { source_sourceKey: { source: "valve", sourceKey: c.sourceKey } },
            create: { source: "valve", sourceKey: c.sourceKey, ...data }, update: data,
          });
        }));
      }
      // Rows that now collide with something Nxeon hosts are removed (they were listed before we hosted them).
      const gone = await db.externalServer.deleteMany({
        where: { source: "valve", game, OR: [{ lastSeenAt: { lt: new Date(Date.now() - PRUNE_AFTER_DAYS * 86_400_000) } }, { connKey: { in: [...nxKeys] } }] },
      });
      pruned = gone.count;
      await db.directoryIngestRun.update({ where: { id: run!.id }, data: { finishedAt: new Date(), fetched: fetched.length, inserted, updated, duplicates: dup, pruned } });
    }
    return { game, fetched: fetched.length, inserted, updated, duplicates: dup, pruned, blocked, dryRun: !opts.apply };
  } catch (e) {
    const msg = e instanceof ValveFetchError ? e.message : e instanceof Error ? e.message : "ingest failed";
    if (run) await db.directoryIngestRun.update({ where: { id: run.id }, data: { finishedAt: new Date(), error: msg.slice(0, 300) } }).catch(() => {});
    throw e;
  }
}
import { Resolver } from "node:dns/promises";

/**
 * Reverse-DNS (PTR) lookups for IP-only directory rows. INGEST TIME ONLY —
 * never call this from a page render. Bounded three ways: a per-lookup timeout,
 * a concurrency cap and a hard cap on lookups per run; anything over budget or
 * failing simply yields no PTR (the row is then judged on its host alone).
 * The reverse function is injectable so tests never touch the network.
 */
export type ReverseFn = (ip: string) => Promise<string[]>;

export const PTR_TIMEOUT_MS = 1500;
export const PTR_CONCURRENCY = 16;
export const PTR_MAX_LOOKUPS = 3000;
export const PTR_TTL_MS = 30 * 86_400_000;

export function systemReverse(timeoutMs = PTR_TIMEOUT_MS): ReverseFn {
  const resolver = new Resolver({ timeout: timeoutMs, tries: 1 });
  return (ip) => resolver.reverse(ip);
}

async function withTimeout<T>(p: Promise<T>, ms: number): Promise<T | null> {
  let t: ReturnType<typeof setTimeout> | undefined;
  try {
    return await Promise.race([p, new Promise<null>((r) => { t = setTimeout(() => r(null), ms); })]);
  } finally { if (t) clearTimeout(t); }
}

/** ip -> first PTR name, or null (none / failed / timed out / over budget). */
export async function resolvePtrs(ips: string[], opts: { reverse?: ReverseFn; timeoutMs?: number; concurrency?: number; maxLookups?: number } = {}): Promise<Map<string, string | null>> {
  const timeoutMs = opts.timeoutMs ?? PTR_TIMEOUT_MS;
  const reverse = opts.reverse ?? systemReverse(timeoutMs);
  const work = [...new Set(ips)].slice(0, opts.maxLookups ?? PTR_MAX_LOOKUPS);
  const out = new Map<string, string | null>();
  let next = 0;
  const worker = async () => {
    while (next < work.length) {
      const ip = work[next++];
      try {
        const names = await withTimeout(reverse(ip), timeoutMs);
        out.set(ip, names && names.length ? names[0] : null);
      } catch { out.set(ip, null); }
    }
  };
  await Promise.all(Array.from({ length: Math.max(1, Math.min(opts.concurrency ?? PTR_CONCURRENCY, work.length || 1)) }, worker));
  return out;
}
/**
 * Ingest public servers from the Steam master list into the directory's
 * ExternalServer table (growth item seo-026).
 *
 *   STEAM_WEB_API_KEY=... npx tsx scripts/directory-ingest.ts [--game valheim,projectzomboid] [--limit 1000] [--apply]
 *
 * DRY RUN by default: fetches, parses, dedupes against everything Nxeon hosts,
 * prints counts, writes nothing. --apply writes, and ONLY when
 * Setting directory_ingest_enabled is true (flip it at /admin/directory).
 *
 * The Valve server-list API terms for republishing the list publicly are
 * UNVERIFIED. Do not enable ingestion until the owner has read them. Meant for
 * a daily timer at most (one request per game, <= 5000 rows each).
 */
import { ingestValveGame } from "../lib/directory-ingest/run";
import { VALVE_APPIDS } from "../lib/directory-ingest/valve";

async function main() {
  const arg = (n: string) => { const i = process.argv.indexOf(`--${n}`); return i >= 0 ? process.argv[i + 1] : undefined; };
  const apply = process.argv.includes("--apply");
  const key = process.env.STEAM_WEB_API_KEY;
  if (!key) { console.error("STEAM_WEB_API_KEY is not set (a free Steam Web API key)."); process.exit(2); }
  const games = (arg("game") ?? "valheim,projectzomboid").split(",").map((s) => s.trim()).filter(Boolean);
  const bad = games.filter((g) => !VALVE_APPIDS[g]);
  if (bad.length) { console.error(`Unsupported: ${bad.join(", ")}. Supported: ${Object.keys(VALVE_APPIDS).join(", ")}`); process.exit(2); }
  const limit = arg("limit") ? Number(arg("limit")) : 1000;
  let failed = 0;
  for (const g of games) {
    try {
      const r = await ingestValveGame(g, { apply, key, limit });
      console.log(`${r.dryRun ? "DRY " : "DONE"} ${g}: fetched ${r.fetched}, new ${r.inserted}, updated ${r.updated}, duplicates dropped ${r.duplicates}, blocked (other hosts) ${r.blocked}, pruned ${r.pruned}`);
    } catch (e) {
      failed++;
      console.error(`FAIL ${g}: ${e instanceof Error ? e.message : e}`);
    }
  }
  process.exit(failed ? 1 : 0);
}
main();
import { db } from "@/lib/db";
import { getSetting } from "@/lib/settings";
import { buildRuleSet, evaluateHost, describeVerdict, type RuleSet, type RuleError } from "@/lib/directory-blocklist";

/**
 * Database side of the competitor-host blocklist. The rules come from the
 * shipped default list + two admin Settings (directory_blocked_hosts_extra /
 * _allow). Nxeon's own play domain is added to the never-block list.
 */
export async function loadRuleSet(): Promise<{ set: RuleSet; errors: RuleError[] }> {
  const [extraText, allowText, freeDomain] = await Promise.all([
    getSetting("directory_blocked_hosts_extra", "").catch(() => ""),
    getSetting("directory_blocked_hosts_allow", "").catch(() => ""),
    getSetting("free_minecraft_domain", "play.nxeon.cloud").catch(() => "play.nxeon.cloud"),
  ]);
  return buildRuleSet({ extraText, allowText, neverBlock: [freeDomain] });
}

/**
 * Re-judge every stored external row against the CURRENT rules using the host
 * and the PTR name stored at ingest (no network). Called after the admin edits
 * the lists, so rows blocked by a removed/allow-listed rule come back and new
 * blocks are recorded. Returns how many rows changed state.
 */
export async function reevaluateExternalBlocks(): Promise<{ checked: number; nowBlocked: number; unblocked: number }> {
  const { set } = await loadRuleSet();
  const rows = await db.externalServer.findMany({ select: { id: true, host: true, port: true, ptrName: true, blockedReason: true, blockedRule: true } });
  let nowBlocked = 0, unblocked = 0;
  const updates: { id: string; reason: string | null; rule: string | null }[] = [];
  for (const r of rows) {
    const v = evaluateHost(r.host, r.port, set, { ptr: r.ptrName });
    const reason = describeVerdict(v), rule = v.rule?.id ?? null;
    if (reason === r.blockedReason && rule === r.blockedRule) continue;
    if (reason && !r.blockedReason) nowBlocked++;
    if (!reason && r.blockedReason) unblocked++;
    updates.push({ id: r.id, reason, rule });
  }
  for (let i = 0; i < updates.length; i += 200) {
    await db.$transaction(updates.slice(i, i + 200).map((u) => db.externalServer.update({ where: { id: u.id }, data: { blockedReason: u.reason, blockedRule: u.rule } })));
  }
  return { checked: rows.length, nowBlocked, unblocked };
}
