/**
 * Scheduler core: runs ONE bounded slice of one provider, resumable via the
 * ModSyncProvider.cursor. Safe to call concurrently from several processes
 * (claim = conditional UPDATE on the provider row with a heartbeat window).
 */
import { db } from "../db";
import { HttpClient } from "./http";
import { PROVIDERS, providerByKey } from "./registry";
import { mirrorVersion } from "./mirror";
import { upsertMod } from "./store";
import type { NormalizedMod, Provider } from "./types";
import { Prisma } from "@prisma/client";

const STALE_RUNNING_MS = 20 * 60_000;
const FULL_EVERY_MS = 7 * 24 * 3600_000;

export interface SliceOpts {
  maxMods?: number;
  budgetMs?: number;
  /** Ignore paused/enabled/nextRunAt (admin "run now" or CLI). */
  force?: boolean;
  mode?: "full" | "recent";
  cacheImages?: boolean;
  mirror?: boolean;
  mirrorLimit?: number;
  log?: (m: string) => void;
}

export interface SliceStats {
  seen: number; created: number; updated: number; failed: number; requests: number; retries: number;
  mirrored: number; mirrorSkipped: number; mirrorFailed: number; mode: string; done: boolean; fullAt?: string | null;
}

/** Env vars a provider needs that are not set (empty = ready). */
export function missingEnv(p: Provider): string[] {
  return (p.requiresEnv ?? []).filter((k) => !process.env[k]);
}

export async function ensureProviderRows(): Promise<void> {
  for (const p of PROVIDERS) {
    await db.modSyncProvider.upsert({
      where: { key: p.key },
      update: {},
      create: { key: p.key, enabled: p.defaultEnabled, intervalMinutes: p.intervalMinutes, nextRunAt: new Date() },
    });
  }
}

/** Record a clear admin-visible status instead of failing when a provider's API key is not configured. */
async function parkNeedsKey(provider: Provider, missing: string[]): Promise<SliceStats> {
  const msg = `Needs ${missing.join(", ")} — ${provider.keyHelp ?? "set it in /opt/nxeon/.env and restart the worker."}`;
  await db.modSyncProvider.update({
    where: { key: provider.key },
