import dgram from "node:dgram";

/**
 * Direct Valve "Source query" liveness probe (A2S_INFO, with the challenge step Valve
 * added in 2020). PURE packet building/parsing + an injectable transport, so every
 * decision is unit-tested with fixture packets and nothing here needs a network.
 *
 * Spec: https://developer.valvesoftware.com/wiki/Server_queries
 *
 *   request   FF FF FF FF 54 "Source Engine Query" 00 [challenge:int32]
 *   challenge FF FF FF FF 41 <challenge:4 bytes>      -> resend the request with it appended
 *   info      FF FF FF FF 49 protocol, name\0, map\0, folder\0, game\0, appid:u16le, players,
 *             max, bots, type, environment, visibility, vac, [The Ship extras], version\0, EDF...
 *
 * PRIVACY / SCOPE (hard rules, mirrored by the tests):
 *  - Only A2S_INFO is ever sent. A2S_PLAYER (player names) and A2S_RULES are NOT implemented
 *    and must not be added: no player-level data is stored by the directory.
 *  - The result drops the server name; only counts, the password flag and the round trip leave
 *    this module.
 *  - Targets are addresses we learned from the Steam list; the caller (lib/directory-liveness.ts)
 *    refuses private/reserved/low ports. Nothing here scans address space.
 */

const HEADER = Buffer.from([0xff, 0xff, 0xff, 0xff]);
const INFO_PAYLOAD = Buffer.concat([Buffer.from([0x54]), Buffer.from("Source Engine Query\0", "latin1")]);

/** The A2S_INFO request; `challenge` (4 bytes from an 0x41 reply) is appended on the second step. */
export function buildInfoRequest(challenge?: Buffer): Buffer {
  if (challenge && challenge.length !== 4) throw new Error("A2S challenge must be 4 bytes");
  return Buffer.concat([HEADER, INFO_PAYLOAD, ...(challenge ? [challenge] : [])]);
}

export type A2sInfo = {
  protocol: number;
  name: string;
  map: string;
  folder: string;
  game: string;
  appId: number;
  players: number;
  maxPlayers: number;
  bots: number;
  /** "d" dedicated | "l" listen | "p" SourceTV, as sent. */
  serverType: string;
  environment: string;
  passworded: boolean;
  vac: boolean;
  version: string;
};

export type A2sParsed =
  | { type: "info"; info: A2sInfo }
  | { type: "challenge"; challenge: Buffer }
  /** A multi-packet reply (header FE FF FF FF). It proves the server answered; we do not reassemble it. */
  | { type: "split" };

class Reader {
  pos = 0;
  constructor(readonly b: Buffer) {}
  u8(): number { if (this.pos >= this.b.length) throw new RangeError("short packet"); return this.b[this.pos++]; }
  u16(): number { if (this.pos + 2 > this.b.length) throw new RangeError("short packet"); const v = this.b.readUInt16LE(this.pos); this.pos += 2; return v; }
  cstr(): string {
    const end = this.b.indexOf(0, this.pos);
    if (end < 0) throw new RangeError("unterminated string");
    const s = this.b.toString("utf8", this.pos, end);
    this.pos = end + 1;
    return s;
  }
}

/** Parse one reply datagram. Returns null for anything that is not a well-formed A2S answer. Never throws. */
export function parseA2sResponse(buf: Buffer): A2sParsed | null {
  try {
    if (!Buffer.isBuffer(buf) || buf.length < 5) return null;
    const h = buf.readInt32LE(0);
    if (h === -2) return { type: "split" };
    if (h !== -1) return null;
    const kind = buf[4];
    if (kind === 0x41) {
      if (buf.length < 9) return null;
      return { type: "challenge", challenge: Buffer.from(buf.subarray(5, 9)) };
    }
    if (kind !== 0x49) return null; // 0x6D is the obsolete GoldSource reply: treated as "no valid answer"
    const r = new Reader(buf);
    r.pos = 5;
    const protocol = r.u8();
    const name = r.cstr(), map = r.cstr(), folder = r.cstr(), game = r.cstr();
    const appId = r.u16();
    const players = r.u8(), maxPlayers = r.u8(), bots = r.u8();
    const serverType = String.fromCharCode(r.u8()), environment = String.fromCharCode(r.u8());
    const passworded = r.u8() === 1, vac = r.u8() === 1;
    if (appId === 2400) { r.u8(); r.u8(); r.u8(); } // The Ship: mode, witnesses, duration
    const version = r.cstr();
    // The Extra Data Flag block (port, steamid, keywords, gameid) is optional and not needed here.
    return { type: "info", info: { protocol, name, map, folder, game, appId, players, maxPlayers, bots, serverType, environment, passworded, vac, version } };
  } catch {
    return null;
  }
}

/** One request/response exchange. Resolves with the first datagram FROM the target, or null on timeout/error. */
export type A2sTransport = (host: string, port: number, payload: Buffer, timeoutMs: number) => Promise<Buffer | null>;

/**
 * Real UDP transport: one short-lived socket per exchange, a single timeout, and replies are only
 * accepted from the exact address/port we sent to (so a spoofed third party cannot answer for it).
 */
export const udpTransport: A2sTransport = (host, port, payload, timeoutMs) =>
  new Promise((resolve) => {
    const sock = dgram.createSocket("udp4");
    let done = false;
    const finish = (v: Buffer | null) => {
      if (done) return;
      done = true;
      clearTimeout(timer);
      try { sock.close(); } catch { /* already closed */ }
      resolve(v);
    };
    const timer = setTimeout(() => finish(null), timeoutMs);
    sock.on("error", () => finish(null));
    sock.on("message", (msg, rinfo) => { if (rinfo.address === host && rinfo.port === port) finish(msg); });
    sock.send(payload, port, host, (err) => { if (err) finish(null); });
  });

export type ProbeFailure = "timeout" | "bad-reply" | "no-challenge-answer" | "implausible";

export type A2sProbeResult =
  | { alive: true; rttMs: number; players: number; maxPlayers: number; passworded: boolean; viaSplit: boolean }
  | { alive: false; reason: ProbeFailure };

/** Player-count ceilings: a server claiming more is spoofing the list. Rust really runs 500+ slots. */
const MAX_SLOTS: Record<string, number> = { rust: 1000 };
export const DEFAULT_MAX_SLOTS = 256;

/** Reject numbers a real server cannot report (spoofed/garbage replies). */
export function plausibleCounts(players: number, maxPlayers: number, game: string): boolean {
  return maxPlayers > 0 && players <= maxPlayers && maxPlayers <= (MAX_SLOTS[game] ?? DEFAULT_MAX_SLOTS);
}

/**
 * Probe one server: request -> (challenge -> request with challenge) -> info. The first send is
 * retried once on silence (UDP loses packets); the second step is not. At most 3 datagrams out.
 */
export async function probeA2s(
  target: { ip: string; port: number; game: string },
  opts: { transport?: A2sTransport; timeoutMs?: number; now?: () => number } = {},
): Promise<A2sProbeResult> {
  const transport = opts.transport ?? udpTransport;
  const timeoutMs = opts.timeoutMs ?? 1500;
  const now = opts.now ?? (() => Date.now());
  const t0 = now();
  let reply = await transport(target.ip, target.port, buildInfoRequest(), timeoutMs);
  if (!reply) reply = await transport(target.ip, target.port, buildInfoRequest(), timeoutMs);
  if (!reply) return { alive: false, reason: "timeout" };
  let parsed = parseA2sResponse(reply);
  if (parsed?.type === "challenge") {
    const second = await transport(target.ip, target.port, buildInfoRequest(parsed.challenge), timeoutMs);
    if (!second) return { alive: false, reason: "no-challenge-answer" };
    parsed = parseA2sResponse(second);
  }
  const rttMs = Math.max(0, now() - t0);
  if (!parsed || parsed.type === "challenge") return { alive: false, reason: "bad-reply" };
  if (parsed.type === "split") return { alive: true, rttMs, players: 0, maxPlayers: 0, passworded: false, viaSplit: true };
  const { players, maxPlayers, passworded } = parsed.info;
  if (!plausibleCounts(players, maxPlayers, target.game)) return { alive: false, reason: "implausible" };
  return { alive: true, rttMs, players, maxPlayers, passworded, viaSplit: false };
}

