  maxPlayers: number;
  bots: number;
  /** "d" dedicated | "l" listen | "p" SourceTV, as sent. */
  serverType: string;
  environment: string;
  passworded: boolean;
  vac: boolean;
  version: string;
};

export type A2sParsed =
  | { type: "info"; info: A2sInfo }
  | { type: "challenge"; challenge: Buffer }
  /** A multi-packet reply (header FE FF FF FF). It proves the server answered; we do not reassemble it. */
  | { type: "split" };

class Reader {
  pos = 0;
  constructor(readonly b: Buffer) {}
  u8(): number { if (this.pos >= this.b.length) throw new RangeError("short packet"); return this.b[this.pos++]; }
  u16(): number { if (this.pos + 2 > this.b.length) throw new RangeError("short packet"); const v = this.b.readUInt16LE(this.pos); this.pos += 2; return v; }
  cstr(): string {
    const end = this.b.indexOf(0, this.pos);
    if (end < 0) throw new RangeError("unterminated string");
    const s = this.b.toString("utf8", this.pos, end);
    this.pos = end + 1;
    return s;
  }
}

/** Parse one reply datagram. Returns null for anything that is not a well-formed A2S answer. Never throws. */
export function parseA2sResponse(buf: Buffer): A2sParsed | null {
  try {
    if (!Buffer.isBuffer(buf) || buf.length < 5) return null;
    const h = buf.readInt32LE(0);
    if (h === -2) return { type: "split" };
    if (h !== -1) return null;
    const kind = buf[4];
    if (kind === 0x41) {
      if (buf.length < 9) return null;
      return { type: "challenge", challenge: Buffer.from(buf.subarray(5, 9)) };
    }
    if (kind !== 0x49) return null; // 0x6D is the obsolete GoldSource reply: treated as "no valid answer"
    const r = new Reader(buf);
    r.pos = 5;
    const protocol = r.u8();
    const name = r.cstr(), map = r.cstr(), folder = r.cstr(), game = r.cstr();
    const appId = r.u16();
    const players = r.u8(), maxPlayers = r.u8(), bots = r.u8();
    const serverType = String.fromCharCode(r.u8()), environment = String.fromCharCode(r.u8());
