    return { type: "info", info: { protocol, name, map, folder, game, appId, players, maxPlayers, bots, serverType, environment, passworded, vac, version } };
  } catch {
    return null;
  }
}

/** One request/response exchange. Resolves with the first datagram FROM the target, or null on timeout/error. */
export type A2sTransport = (host: string, port: number, payload: Buffer, timeoutMs: number) => Promise<Buffer | null>;

/**
 * Real UDP transport: one short-lived socket per exchange, a single timeout, and replies are only
 * accepted from the exact address/port we sent to (so a spoofed third party cannot answer for it).
 */
export const udpTransport: A2sTransport = (host, port, payload, timeoutMs) =>
  new Promise((resolve) => {
    const sock = dgram.createSocket("udp4");
    let done = false;
    const finish = (v: Buffer | null) => {
      if (done) return;
      done = true;
      clearTimeout(timer);
      try { sock.close(); } catch { /* already closed */ }
      resolve(v);
    };
    const timer = setTimeout(() => finish(null), timeoutMs);
    sock.on("error", () => finish(null));
    sock.on("message", (msg, rinfo) => { if (rinfo.address === host && rinfo.port === port) finish(msg); });
    sock.send(payload, port, host, (err) => { if (err) finish(null); });
  });

