    ingestOn, sweepOn, probeOn, showOn, storageCountry, termsReviewedBy,
    intervalMin: clampIntervalMin(interval),
    legalProblems: steamLegalGate({ storageCountry, termsReviewedBy }),
    hasKey: !!process.env.STEAM_WEB_API_KEY,
  };
