import { db } from "@/lib/db";
import { getSettingBool } from "@/lib/settings";
import { probeA2s, udpTransport, type A2sTransport, type A2sProbeResult } from "./a2s";
import { ensureSource } from "./sweep";
import {
  ALIVE_REPROBE_MS, DEAD_REPROBE_MS, FAIL_RETRY_MS, PROBE_CONCURRENCY, PROBE_RATE_PER_SEC,
  isProbeBlackout, nextProbeState, probeTarget, selectProbeBatch, type ProbeOutcome, type ProbeRow,
} from "@/lib/directory-liveness";

/**
 * The liveness prober tick (worker/directory.ts calls it about once a minute). It reads ONLY stored Steam-list
 * rows (addresses we were given), picks the due ones (lib/directory-liveness.ts), sends each ONE A2S_INFO exchange
 * at about PROBE_RATE_PER_SEC per second overall with at most PROBE_CONCURRENCY in flight and one in flight per IP,
 * then records ALIVE / failure counts / DEAD. No player names are requested or stored, no address space is scanned.
 *
 * Runs only when Setting directory_probe_enabled AND directory_ingest_enabled are on AND the worker process has
 * NXEON_DIRECTORY_PROBE=1 (the owner chooses which box sends the packets; the plan recommends not the primary).
 */
export const PROBE_SOURCE = "probe";
const TICK_BUDGET_MS = 50_000;
const BATCH = 450;
const CANDIDATE_LIMIT = 4000;

export type ProbeReport = {
  skipped?: "kill-switch" | "disabled" | "not-this-box" | "running";
  probed: number; alive: number; failed: number; newlyDead: number; blackout: boolean; due: number;
  reasons: Record<string, number>;
};

const empty = (): ProbeReport => ({ probed: 0, alive: 0, failed: 0, newlyDead: 0, blackout: false, due: 0, reasons: {} });
const sleepMs = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

function toOutcome(r: A2sProbeResult): ProbeOutcome {
  return r.alive ? { alive: true, rttMs: r.rttMs, players: r.players, maxPlayers: r.maxPlayers, viaSplit: r.viaSplit } : { alive: false, reason: r.reason };
}

export async function directoryProbeTick(opts: {
  now?: number; transport?: A2sTransport; batch?: number; ratePerSec?: number; concurrency?: number;
  envOk?: boolean; budgetMs?: number; sleep?: (ms: number) => Promise<void>;
} = {}): Promise<ProbeReport> {
  const rep = empty();
  if (process.env.DIRECTORY_SWEEP_DISABLED === "1") return { ...rep, skipped: "kill-switch" };
  if (!(opts.envOk ?? process.env.NXEON_DIRECTORY_PROBE === "1")) return { ...rep, skipped: "not-this-box" };
  const [ingestOn, probeOn] = await Promise.all([getSettingBool("directory_ingest_enabled", false), getSettingBool("directory_probe_enabled", false)]);
  if (!ingestOn || !probeOn) return { ...rep, skipped: "disabled" };

  const now = opts.now ?? Date.now();
  await ensureSource(PROBE_SOURCE);
  const claimed = await db.directorySource.updateMany({
    where: { key: PROBE_SOURCE, OR: [{ runningUntil: null }, { runningUntil: { lt: new Date(now) } }] },
    data: { runningUntil: new Date(now + 2 * 60_000) },
  });
  if (!claimed.count) return { ...rep, skipped: "running" };

  let error: string | null = null;
  try {
    const cutoff = (ms: number) => new Date(now - ms);
    const rows = await db.externalServer.findMany({
      where: {
        source: "valve", hidden: false, blockedReason: null, ip: { not: null }, lastSeenAt: { gte: cutoff(3 * 86_400_000) },
        OR: [
          { lastProbeAt: null },
          { probeStatus: "DEAD", lastProbeAt: { lt: cutoff(DEAD_REPROBE_MS) } },
          { consecutiveFails: { gt: 0 }, probeStatus: { not: "DEAD" }, lastProbeAt: { lt: cutoff(FAIL_RETRY_MS) } },
          { consecutiveFails: 0, probeStatus: { not: "DEAD" }, lastProbeAt: { lt: cutoff(ALIVE_REPROBE_MS) } },
        ],
      },
      select: { id: true, ip: true, port: true, queryPort: true, game: true, probeStatus: true, consecutiveFails: true, lastProbeAt: true, lastAliveAt: true },
      orderBy: [{ lastProbeAt: { sort: "asc", nulls: "first" } }],
      take: CANDIDATE_LIMIT,
    });
    const batch = selectProbeBatch(rows as ProbeRow[], now, { batch: opts.batch ?? BATCH });
    rep.due = rows.length;

    const transport = opts.transport ?? udpTransport;
    const rate = Math.max(1, opts.ratePerSec ?? PROBE_RATE_PER_SEC), gap = 1000 / rate;
    const cap = Math.max(1, opts.concurrency ?? PROBE_CONCURRENCY);
    const sleep = opts.sleep ?? sleepMs;
    const deadline = Date.now() + (opts.budgetMs ?? TICK_BUDGET_MS);
    const results: { row: ProbeRow; outcome: ProbeOutcome }[] = [];
    const ipChain = new Map<string, Promise<void>>();
    const inflight = new Set<Promise<void>>();
    for (const row of batch) {
      if (Date.now() > deadline) break;
      while (inflight.size >= cap) await Promise.race(inflight);
      const t = probeTarget(row)!; // selectProbeBatch only returns probeable rows
      // One in flight per IP: chain behind any earlier probe to the same address.
      const prev = ipChain.get(t.ip) ?? Promise.resolve();
      const p: Promise<void> = prev.then(async () => {
        let outcome: ProbeOutcome;
        try { outcome = toOutcome(await probeA2s(t, { transport })); } catch { outcome = { alive: false, reason: "error" }; }
        results.push({ row, outcome });
      });
      ipChain.set(t.ip, p);
      const tracked = p.finally(() => { inflight.delete(tracked); });
      inflight.add(tracked);
      await sleep(gap);
    }
    await Promise.all(inflight);

    rep.probed = results.length;
    rep.blackout = isProbeBlackout(results.map((r) => ({ alive: r.outcome.alive })));
    for (const r of results) {
      if (r.outcome.alive) rep.alive++;
      else { rep.failed++; const k = r.outcome.reason; rep.reasons[k] = (rep.reasons[k] ?? 0) + 1; }
    }
    if (rep.blackout) {
      // Our own egress is the likelier culprit than every probed server dying at once: write nothing.
      error = `Blackout: ${results.length} probes, none answered. No state was recorded (check UDP egress from this box).`;
    } else {
      const at = new Date(now);
      for (let i = 0; i < results.length; i += 100) {
        await db.$transaction(results.slice(i, i + 100).map(({ row, outcome }) => {
          const u = nextProbeState(row, outcome, at);
          if (u.probeStatus === "DEAD" && row.probeStatus !== "DEAD") rep.newlyDead++;
          return db.externalServer.update({
            where: { id: row.id },
            data: {
              probeStatus: u.probeStatus, consecutiveFails: u.consecutiveFails, lastProbeAt: u.lastProbeAt,
              lastAliveAt: u.lastAliveAt, latencyMs: u.latencyMs,
              ...(u.players !== undefined ? { players: u.players, maxPlayers: u.maxPlayers } : {}),
            },
          });
        }));
      }
    }
  } catch (e) {
    error = (e instanceof Error ? e.message : "probe tick failed").slice(0, 300);
  } finally {
    await db.directorySource.update({
      where: { key: PROBE_SOURCE },
      data: {
        runningUntil: null, lastRunAt: new Date(now),
        ...(error ? { lastError: error, lastErrorAt: new Date(now), consecutiveErrors: { increment: 1 } } : { lastOkAt: new Date(now), lastError: null, lastErrorAt: null, consecutiveErrors: 0 }),
        stats: { probed: rep.probed, alive: rep.alive, failed: rep.failed, newlyDead: rep.newlyDead, blackout: rep.blackout, due: rep.due, reasons: rep.reasons },
      },
    });
  }
  return rep;
}
EOF

