cat > scripts/directory-probe.ts <<'EOF'
/**
 * One-off liveness probe of stored Steam-list rows (directory phase 1). DRY RUN by default: it sends the
 * real A2S_INFO queries to the chosen rows and prints what came back, writing nothing. --apply records the
 * results exactly as the worker tick does.
 *
 *   npx tsx scripts/directory-probe.ts [--game valheim] [--limit 20] [--apply]
 *
 * Sends real UDP packets to third-party game servers: run it deliberately, small (--limit), from the box the
 * owner chose for probing. Only rows ALREADY in ExternalServer (addresses from the Steam list) are used;
 * nothing is discovered or scanned, and no player names are requested.
 */
import { db } from "../lib/db";
import { probeA2s } from "../lib/directory-ingest/a2s";
import { nextProbeState, probeTarget, type ProbeOutcome } from "../lib/directory-liveness";

async function main() {
  const arg = (n: string) => { const i = process.argv.indexOf(`--${n}`); return i >= 0 ? process.argv[i + 1] : undefined; };
  const apply = process.argv.includes("--apply");
  const limit = Math.min(Math.max(Number(arg("limit") ?? 20) || 20, 1), 200);
  const game = arg("game");
  const rows = await db.externalServer.findMany({
    where: { source: "valve", hidden: false, blockedReason: null, ip: { not: null }, ...(game ? { game } : {}) },
    orderBy: [{ lastProbeAt: { sort: "asc", nulls: "first" } }], take: limit,
  });
  let alive = 0, n = 0;
  for (const r of rows) {
    const t = probeTarget(r);
    if (!t) { console.log(`SKIP ${r.game} ${r.host}:${r.port} (not a probeable public address/port)`); continue; }
    const res = await probeA2s(t);
    n++;
    const o: ProbeOutcome = res.alive ? { alive: true, rttMs: res.rttMs, players: res.players, maxPlayers: res.maxPlayers, viaSplit: res.viaSplit } : { alive: false, reason: res.reason };
    if (res.alive) alive++;
    console.log(`${res.alive ? "ALIVE" : "DEAD "} ${r.game} ${t.ip}:${t.port} ${res.alive ? `${res.players}/${res.maxPlayers} ${res.rttMs}ms` : res.reason}`);
    if (apply) {
      const u = nextProbeState(r, o, new Date());
      await db.externalServer.update({ where: { id: r.id }, data: {
        probeStatus: u.probeStatus, consecutiveFails: u.consecutiveFails, lastProbeAt: u.lastProbeAt, lastAliveAt: u.lastAliveAt, latencyMs: u.latencyMs,
        ...(u.players !== undefined ? { players: u.players, maxPlayers: u.maxPlayers } : {}),
      } });
    }
    await new Promise((r2) => setTimeout(r2, 100)); // 10 per second at most
  }
  console.log(`${apply ? "APPLIED" : "DRY RUN"}: ${n} probed, ${alive} answered.`);
  await db.$disconnect();
}
main();
EOF
