  { addr: "203.0.113.5:2457", gameport: 2456, name: "  Odin's Hall  EU ", appid: 892970, version: "0.221.4", players: 7, max_players: 10, bots: 0, map: "Dedicated", dedicated: true, gametype: "pvp,modded,eu" },
  { addr: "203.0.113.5:2457", gameport: 2456, name: "dup row same server", dedicated: true },
  { addr: "10.0.0.2:2457", gameport: 2456, name: "private address", dedicated: true },
  { addr: "198.51.100.7:27016", name: "No game port", players: 3, max_players: 20, dedicated: true },
  { addr: "198.51.100.8:27016", name: "", dedicated: true },
  { addr: "198.51.100.9:27016", name: "listen server", dedicated: false },
  { addr: "bad", name: "x" },
] } };

test("parseValveResponse: keeps public dedicated servers, drops private/dup/blank", () => {
