  for (const p of s.sent) assert.equal(p[4], 0x54, "request type must be A2S_INFO (0x54), never A2S_PLAYER (0x55) or A2S_RULES (0x56)");
  assert.deepEqual(Object.keys(r).sort(), ["alive", "maxPlayers", "passworded", "players", "rttMs", "viaSplit"]);
  assert.ok(!JSON.stringify(r).includes("Example Valheim Server"));
