test("real UDP transport on loopback: challenge handshake end to end, spoofed replies ignored", async () => {
  const server = dgram.createSocket("udp4");
  const stranger = dgram.createSocket("udp4");
  await new Promise<void>((r) => server.bind(0, "127.0.0.1", r));
  await new Promise<void>((r) => stranger.bind(0, "127.0.0.1", r));
  const port = server.address().port;
  server.on("message", (msg, rinfo) => {
    // A third socket tries to answer first: it must be ignored (wrong source port).
    stranger.send(pkt("info_spoof_players_gt_max"), rinfo.port, "127.0.0.1");
    const withChallenge = msg.length > 25;
    setTimeout(() => server.send(withChallenge ? pkt("info_valheim") : pkt("challenge"), rinfo.port, rinfo.address), 20);
  });
  try {
    const r = await probeA2s({ ip: "127.0.0.1", port, game: "valheim" }, { transport: udpTransport, timeoutMs: 1000 });
    assert.equal(r.alive, true);
    if (r.alive) assert.equal(r.players, 7);
    // and a closed port is simply a timeout
    const dead = await probeA2s({ ip: "127.0.0.1", port: 9, game: "valheim" }, { transport: udpTransport, timeoutMs: 150 });
    assert.equal(dead.alive, false);
  } finally { server.close(); stranger.close(); }
});
