import test from "node:test";
import assert from "node:assert/strict";
import {
  isPublicIpv4, isProbeablePort, probeTarget, dueAt, selectProbeBatch, nextProbeState, isProbeBlackout, isRowPublic,
  liveCountsFresh, PROBE_RATE_PER_SEC, PROBE_CONCURRENCY, DEAD_AFTER_FAILS, ALIVE_REPROBE_MS, FAIL_RETRY_MS, DEAD_REPROBE_MS,
  FRESH_COUNT_MS, type ProbeRow,
} from "../lib/directory-liveness";
import { filterLiveRows } from "../lib/server-directory-data";

const NOW = Date.parse("2026-10-04T12:00:00Z");
const ago = (ms: number) => new Date(NOW - ms);
const row = (o: Partial<ProbeRow> & { id: string }): ProbeRow => ({
  ip: "5.9.1.1", port: 2456, queryPort: 2457, game: "valheim", probeStatus: "UNKNOWN", consecutiveFails: 0, lastProbeAt: null, lastAliveAt: null, ...o,
});

test("only public routable IPv4 is ever probed", () => {
  for (const ok of ["5.9.1.1", "8.8.8.8", "51.79.162.96", "100.63.255.255", "100.128.0.1", "172.15.0.1", "172.32.0.1", "223.255.255.255"]) assert.equal(isPublicIpv4(ok), true, ok);
  for (const bad of ["0.1.2.3", "10.1.2.3", "127.0.0.1", "100.64.0.1", "100.127.255.255", "169.254.1.1", "172.16.0.1", "172.31.255.255", "192.168.1.1",
    "192.0.0.1", "192.0.2.5", "198.18.0.1", "198.19.9.9", "198.51.100.7", "203.0.113.5", "224.0.0.1", "239.1.1.1", "240.0.0.1", "255.255.255.255", "1.2.3", "a.b.c.d", "256.1.1.1", ""]) assert.equal(isPublicIpv4(bad), false, bad);
});

test("ports: >= 1024 only, never a well-known service port", () => {
  for (const ok of [1024, 2457, 27015, 27017, 28015, 65535]) assert.equal(isProbeablePort(ok), true, String(ok));
  for (const bad of [0, 22, 25, 53, 80, 443, 1023, 3306, 3389, 5432, 6379, 65536, 27015.5, -1]) assert.equal(isProbeablePort(bad), false, String(bad));
});

test("probeTarget uses the QUERY port (stored queryPort, else the join port) and refuses unsafe rows", () => {
  assert.deepEqual(probeTarget({ ip: "5.9.1.1", port: 2456, queryPort: 2457, game: "valheim" }), { ip: "5.9.1.1", port: 2457, game: "valheim" });
  assert.deepEqual(probeTarget({ ip: "5.9.1.1", port: 27015, queryPort: null, game: "cs2" }), { ip: "5.9.1.1", port: 27015, game: "cs2" });
  assert.equal(probeTarget({ ip: null, port: 2456, queryPort: null, game: "valheim" }), null);
  assert.equal(probeTarget({ ip: "10.0.0.5", port: 2456, queryPort: null, game: "valheim" }), null);
  assert.equal(probeTarget({ ip: "5.9.1.1", port: 22, queryPort: null, game: "valheim" }), null);
});

test("scheduling: new first, failing next, routine after 30 min, dead daily", () => {
  assert.equal(dueAt(row({ id: "a" })), 0);
  const alive = row({ id: "b", probeStatus: "ALIVE", lastProbeAt: ago(10 * 60_000) });
  assert.ok(dueAt(alive) > NOW, "10 minutes after a good probe: not due");
  assert.ok(dueAt(row({ id: "b2", probeStatus: "ALIVE", lastProbeAt: ago(ALIVE_REPROBE_MS + 1) })) <= NOW);
  assert.ok(dueAt(row({ id: "c", consecutiveFails: 1, lastProbeAt: ago(FAIL_RETRY_MS - 1000) })) > NOW);
  assert.ok(dueAt(row({ id: "c2", consecutiveFails: 1, lastProbeAt: ago(FAIL_RETRY_MS + 1) })) <= NOW);
  assert.ok(dueAt(row({ id: "d", probeStatus: "DEAD", consecutiveFails: 3, lastProbeAt: ago(DEAD_REPROBE_MS - 1000) })) > NOW);
  assert.ok(dueAt(row({ id: "d2", probeStatus: "DEAD", consecutiveFails: 3, lastProbeAt: ago(DEAD_REPROBE_MS + 1) })) <= NOW);
});

test("batch: priority order, total cap, per-IP and per-/24 politeness, unprobeable rows skipped", () => {
  const rows: ProbeRow[] = [
    row({ id: "routine", ip: "5.9.2.1", probeStatus: "ALIVE", lastProbeAt: ago(ALIVE_REPROBE_MS * 2) }),
    row({ id: "dead", ip: "5.9.3.1", probeStatus: "DEAD", consecutiveFails: 3, lastProbeAt: ago(DEAD_REPROBE_MS * 2) }),
    row({ id: "failing", ip: "5.9.4.1", consecutiveFails: 1, lastProbeAt: ago(FAIL_RETRY_MS * 2) }),
    row({ id: "new", ip: "5.9.5.1" }),
    row({ id: "fresh", ip: "5.9.6.1", probeStatus: "ALIVE", lastProbeAt: ago(60_000) }),
    row({ id: "private", ip: "10.0.0.9" }),
    row({ id: "lowport", ip: "5.9.7.1", port: 22, queryPort: null }),
  ];
  assert.deepEqual(selectProbeBatch(rows, NOW, { batch: 10 }).map((r) => r.id), ["new", "failing", "routine", "dead"]);
  assert.deepEqual(selectProbeBatch(rows, NOW, { batch: 2 }).map((r) => r.id), ["new", "failing"]);
  const sameIp = Array.from({ length: 6 }, (_, i) => row({ id: `p${i}`, ip: "5.9.8.8", port: 2456 + i, queryPort: null }));
  assert.equal(selectProbeBatch(sameIp, NOW, { batch: 100 }).length, 2, "at most 2 per IP per tick");
  const sameNet = Array.from({ length: 80 }, (_, i) => row({ id: `n${i}`, ip: `5.9.9.${i + 1}` }));
  assert.equal(selectProbeBatch(sameNet, NOW, { batch: 1000 }).length, 30, "at most 30 per /24 per tick");
});

test("rate and concurrency stay within the agreed bounds", () => {
  assert.ok(PROBE_RATE_PER_SEC <= 10);
  assert.ok(PROBE_CONCURRENCY <= 64);
  assert.equal(DEAD_AFTER_FAILS, 3);
});

test("state machine: alive resets; a row dies only after 3 consecutive failures; one success revives", () => {
  const t = new Date(NOW);
  let s = nextProbeState({ probeStatus: "UNKNOWN", consecutiveFails: 0, lastAliveAt: null }, { alive: true, rttMs: 40, players: 3, maxPlayers: 10 }, t);
  assert.equal(s.probeStatus, "ALIVE"); assert.equal(s.consecutiveFails, 0); assert.equal(s.players, 3); assert.equal(s.latencyMs, 40);
  const f1 = nextProbeState({ probeStatus: s.probeStatus, consecutiveFails: s.consecutiveFails, lastAliveAt: s.lastAliveAt }, { alive: false, reason: "timeout" }, t);
  assert.equal(f1.probeStatus, "ALIVE", "one failure is a blip, not death"); assert.equal(f1.consecutiveFails, 1);
  const f2 = nextProbeState(f1, { alive: false, reason: "timeout" }, t);
  assert.equal(f2.probeStatus, "ALIVE"); assert.equal(f2.consecutiveFails, 2);
  const f3 = nextProbeState(f2, { alive: false, reason: "timeout" }, t);
  assert.equal(f3.probeStatus, "DEAD"); assert.equal(f3.consecutiveFails, 3);
  assert.equal(f3.lastAliveAt?.getTime(), NOW, "last time it answered is kept");
  const back = nextProbeState(f3, { alive: true, rttMs: 5, players: 0, maxPlayers: 8 }, t);
  assert.equal(back.probeStatus, "ALIVE"); assert.equal(back.consecutiveFails, 0);
  const never = nextProbeState({ probeStatus: "UNKNOWN", consecutiveFails: 2, lastAliveAt: null }, { alive: false, reason: "x" }, t);
  assert.equal(never.probeStatus, "DEAD"); assert.equal(never.lastAliveAt, null);
  assert.equal(nextProbeState({ probeStatus: "UNKNOWN", consecutiveFails: 0, lastAliveAt: null }, { alive: false, reason: "x" }, t).probeStatus, "UNKNOWN");
});

test("a split reply revives a row without overwriting its counts; absurd latency is clamped", () => {
  const u = nextProbeState({ probeStatus: "UNKNOWN", consecutiveFails: 1, lastAliveAt: null }, { alive: true, rttMs: 9_999_999, players: 0, maxPlayers: 0, viaSplit: true }, new Date(NOW));
  assert.equal(u.probeStatus, "ALIVE");
  assert.equal(u.players, undefined);
  assert.equal(u.latencyMs, 60_000);
});

test("blackout: 20+ probes with zero answers is our network, not 20 dead servers", () => {
  assert.equal(isProbeBlackout(Array.from({ length: 20 }, () => ({ alive: false }))), true);
  assert.equal(isProbeBlackout(Array.from({ length: 19 }, () => ({ alive: false }))), false);
  assert.equal(isProbeBlackout([...Array.from({ length: 30 }, () => ({ alive: false })), { alive: true }]), false);
});

test("public visibility: DEAD never; prober ON needs a recent answer; prober OFF trusts the list", () => {
  const seen = ago(60_000);
  const mk = (probeStatus: string, lastAliveAt: Date | null) => ({ probeStatus, lastAliveAt, lastSeenAt: seen });
  assert.equal(isRowPublic(mk("DEAD", ago(1000)), { probeOn: true, now: NOW }), false);
  assert.equal(isRowPublic(mk("DEAD", ago(1000)), { probeOn: false, now: NOW }), false);
  assert.equal(isRowPublic(mk("UNKNOWN", null), { probeOn: false, now: NOW }), true);
  assert.equal(isRowPublic(mk("UNKNOWN", null), { probeOn: true, now: NOW }), false, "unverified is not shown once probing is on");
  assert.equal(isRowPublic(mk("ALIVE", ago(60_000)), { probeOn: true, now: NOW }), true);
  assert.equal(isRowPublic(mk("ALIVE", ago(25 * 3600_000)), { probeOn: true, now: NOW }), false, "an answer older than 24 h no longer counts");
  assert.equal(filterLiveRows([mk("ALIVE", ago(1000)), mk("DEAD", null), mk("UNKNOWN", null)], false, NOW).length, 2);
  assert.equal(filterLiveRows([mk("ALIVE", ago(1000)), mk("DEAD", null), mk("UNKNOWN", null)], true, NOW).length, 1);
});

test("player counts count as live only while under an hour old", () => {
  assert.equal(liveCountsFresh({ lastSeenAt: ago(FRESH_COUNT_MS - 1000), lastAliveAt: null }, NOW), true);
  assert.equal(liveCountsFresh({ lastSeenAt: ago(3 * 3600_000), lastAliveAt: null }, NOW), false);
  assert.equal(liveCountsFresh({ lastSeenAt: ago(3 * 3600_000), lastAliveAt: ago(60_000) }, NOW), true, "a recent probe refreshes the numbers");
});
