import test from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import {
  clampIntervalMin, gameIntervalMs, dueGames, backoffMs, breakerDecision, callsRemaining, dayKey, isSuspiciousShrink, sweepGate,
  MAX_GAMES_PER_TICK, BACKOFF_MAX_MS, BREAKER_AFTER_ERRORS, BREAKER_OPEN_MS,
} from "../lib/directory-ingest/schedule";
import { VALVE_APPIDS, parseValveResponse } from "../lib/directory-ingest/valve";
import { STEAM_DAILY_CALL_CAP, STEAM_TERMS_DAILY_LIMIT, steamAttributionHtml, steamLegalGate, steamPrivacyDraft } from "../lib/directory-steam";
import { redactKey } from "../lib/directory-ingest/sweep";
import { SETTINGS_DEFAULTS } from "../lib/settings";

const NOW = Date.parse("2026-10-04T12:00:00Z");
const ago = (ms: number) => new Date(NOW - ms);
const H = 3600_000;

test("the 11 supported games are exactly the ones with a Steam app id", () => {
  assert.deepEqual(Object.keys(VALVE_APPIDS).sort(), ["ark", "cs2", "conan", "gmod", "l4d2", "projectzomboid", "rust", "sdtd", "tf2", "unturned", "valheim"].sort());
});

test("interval: clamped 30..1440 min; the big lists run at 3x", () => {
  assert.equal(clampIntervalMin(5), 30);
  assert.equal(clampIntervalMin(99999), 1440);
  assert.equal(clampIntervalMin(NaN), 60);
  assert.equal(gameIntervalMs("valheim", 60), 60 * 60_000);
  assert.equal(gameIntervalMs("rust", 60), 3 * 60 * 60_000);
});

test("due games: never-run first, longest-waiting first, bounded per tick, force ignores the schedule", () => {
  const games = Object.keys(VALVE_APPIDS);
  const last = new Map<string, Date | null>();
  assert.equal(dueGames(games, last, NOW, { baseMin: 60 }).length, MAX_GAMES_PER_TICK);
  for (const g of games) last.set(g, ago(10 * 60_000)); // everything refreshed 10 min ago
  assert.deepEqual(dueGames(games, last, NOW, { baseMin: 60 }), []);
  assert.equal(dueGames(games, last, NOW, { baseMin: 60, force: true, max: 20 }).length, 11);
  last.set("valheim", ago(61 * 60_000)); last.set("rust", ago(61 * 60_000)); last.set("tf2", ago(2 * H));
  assert.deepEqual(dueGames(games, last, NOW, { baseMin: 60 }), ["tf2", "valheim"], "rust is on the 3 h schedule, so not due at 61 min");
  last.set("rust", ago(3 * H + 1));
  assert.deepEqual(dueGames(games, last, NOW, { baseMin: 60, max: 3 }), ["rust", "tf2", "valheim"]);
});

test("backoff doubles from 5 minutes, caps at 6 h, honours Retry-After", () => {
  assert.equal(backoffMs(1), 5 * 60_000);
  assert.equal(backoffMs(2), 10 * 60_000);
  assert.equal(backoffMs(3), 20 * 60_000);
  assert.equal(backoffMs(40), BACKOFF_MAX_MS);
  assert.equal(backoffMs(1, 3600), 3600_000);
  assert.equal(backoffMs(1, 999_999), BACKOFF_MAX_MS);
  assert.equal(backoffMs(0), 5 * 60_000);
});

test("circuit breaker: opens after repeated failures; 401/403 opens it AND disables the sweep", () => {
  assert.deepEqual(breakerDecision(1, 500), { open: false, disable: false, openMs: 0 });
  assert.deepEqual(breakerDecision(BREAKER_AFTER_ERRORS - 1), { open: false, disable: false, openMs: 0 });
  assert.deepEqual(breakerDecision(BREAKER_AFTER_ERRORS), { open: true, disable: false, openMs: BREAKER_OPEN_MS });
  assert.deepEqual(breakerDecision(1, 403), { open: true, disable: true, openMs: BREAKER_OPEN_MS });
  assert.equal(breakerDecision(1, 401).disable, true);
  assert.equal(breakerDecision(1, 429).disable, false);
});

test("call budget: our cap is far below Valve's, resets each UTC day", () => {
  assert.ok(STEAM_DAILY_CALL_CAP <= STEAM_TERMS_DAILY_LIMIT / 10);
  const today = dayKey(NOW);
  assert.equal(callsRemaining({ callsDay: today, callsToday: 5 }, NOW), STEAM_DAILY_CALL_CAP - 5);
  assert.equal(callsRemaining({ callsDay: "2026-10-03", callsToday: STEAM_DAILY_CALL_CAP }, NOW), STEAM_DAILY_CALL_CAP, "yesterday's count does not carry over");
  assert.equal(callsRemaining({ callsDay: today, callsToday: STEAM_DAILY_CALL_CAP + 50 }, NOW), 0);
  // 11 games, each refreshed at least hourly (rust/cs2/gmod every 3 h): well under the cap even at the 30 minute floor.
  const perDay = Object.keys(VALVE_APPIDS).reduce((n, g) => n + (24 * 3600_000) / gameIntervalMs(g, 30), 0);
  assert.ok(perDay < STEAM_DAILY_CALL_CAP / 2, `${perDay} calls/day at the fastest schedule`);
});

test("shrink guard: a list that collapses keeps old rows", () => {
  assert.equal(isSuspiciousShrink(100, 39), true);
  assert.equal(isSuspiciousShrink(100, 40), false);
  assert.equal(isSuspiciousShrink(10, 0), false, "tiny lists are allowed to empty out");
  assert.equal(isSuspiciousShrink(0, 500), false);
});

const open = { envKill: false, ingestOn: true, sweepOn: true, legalProblems: [] as string[], hasKey: true, circuitOpenUntil: null, nextAttemptAt: null, runningUntil: null, remainingCalls: 10, now: NOW };

test("gate order: env kill > settings off > legal checkpoints > key > claim > breaker > backoff > budget", () => {
  assert.equal(sweepGate(open), null);
  assert.equal(sweepGate({ ...open, envKill: true, ingestOn: false }), "kill-switch");
  assert.equal(sweepGate({ ...open, ingestOn: false }), "disabled", "the existing directory_ingest_enabled flag is honoured");
  assert.equal(sweepGate({ ...open, sweepOn: false }), "disabled");
  assert.equal(sweepGate({ ...open, legalProblems: ["x"], hasKey: false }), "legal-gate");
  assert.equal(sweepGate({ ...open, hasKey: false }), "no-key");
  assert.equal(sweepGate({ ...open, runningUntil: new Date(NOW + 1000) }), "running");
  assert.equal(sweepGate({ ...open, runningUntil: new Date(NOW - 1000) }), null, "a stale claim does not block");
  assert.equal(sweepGate({ ...open, circuitOpenUntil: new Date(NOW + 1000), nextAttemptAt: new Date(NOW + 1000) }), "circuit-open");
  assert.equal(sweepGate({ ...open, nextAttemptAt: new Date(NOW + 1000) }), "backoff");
  assert.equal(sweepGate({ ...open, nextAttemptAt: new Date(NOW - 1000) }), null);
  assert.equal(sweepGate({ ...open, remainingCalls: 0 }), "budget");
});

test("everything defaults OFF / blank", () => {
  for (const k of ["directory_ingest_enabled", "directory_external_show", "directory_sweep_enabled", "directory_probe_enabled"] as const) assert.equal(SETTINGS_DEFAULTS[k], "false", k);
  assert.equal(SETTINGS_DEFAULTS.directory_storage_country, "");
  assert.equal(SETTINGS_DEFAULTS.directory_steam_terms_reviewed_by, "");
});

test("legal gate: both checkpoints must be recorded", () => {
  assert.equal(steamLegalGate({ storageCountry: "", termsReviewedBy: "" }).length, 2);
  assert.equal(steamLegalGate({ storageCountry: "Canada", termsReviewedBy: "  " }).length, 1);
  assert.equal(steamLegalGate({ storageCountry: " Canada ", termsReviewedBy: "A. Owner 2026-10-05" }).length, 0);
});

test("attribution: Valve name + Steam link, followed (no nofollow), no endorsement/host implication", () => {
  for (const logo of [false, true]) {
    const h = steamAttributionHtml({ logo });
    assert.match(h, /href="https:\/\/store\.steampowered\.com\/" rel="noopener"/);
    assert.match(h, /Valve Corporation/);
    assert.match(h, /not affiliated with, endorsed by or sponsored by Valve/);
    assert.ok(!/nofollow|ugc/i.test(h), "the terms forbid nofollow on Valve links");
    assert.ok(!/powered by|provided by valve|courtesy of|in partnership|official/i.test(h), "must not imply Valve provides or endorses the data");
    assert.equal(h.includes("<img"), logo);
    assert.equal((h.match(/<a /g) ?? []).every((_, i, a) => a.length >= 1), true);
  }
});

test("privacy draft takes the storage country from config and states what is (not) stored", () => {
  const t = steamPrivacyDraft({ country: "Canada", contact: "support@nxeon.cloud" });
  assert.match(t, /stored? in Canada|store this data in Canada/);
