/**
 * Directory phase 1 against a THROWAWAY Postgres (never the shared one). Skipped unless
 * DIRECTORY_TEST_DATABASE_URL is set, e.g.
 *   DIRECTORY_TEST_DATABASE_URL=postgresql://x@127.0.0.1:54399/dirp1 npx tsx --test test/directory-phase1-db.test.ts
 * after `DATABASE_URL=<that url> npx prisma db push`. Steam is a recorded-shape fixture served through an injected
 * fetch, DNS is an injected reverse function and probes go through an injected transport: no network of any kind.
 */
import test from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";

const URL_ = process.env.DIRECTORY_TEST_DATABASE_URL;
const T = URL_ ? test : test.skip;
