  const { db } = await import("../lib/db");
  const { setSetting } = await import("../lib/settings");
  const sweep = await import("../lib/directory-ingest/sweep");
  const prober = await import("../lib/directory-ingest/prober");
  const data = await import("../lib/server-directory-data");
  return { db, setSetting, ...sweep, ...prober, ...data };
}

async function reset(m: Awaited<ReturnType<typeof mods>>) {
  await m.db.externalServer.deleteMany();
  await m.db.directoryIngestRun.deleteMany();
  await m.db.directorySource.deleteMany();
  await m.db.setting.deleteMany();
}
async function enable(m: Awaited<ReturnType<typeof mods>>, o: { legal?: boolean; sweep?: boolean; ingest?: boolean } = {}) {
  await m.setSetting("directory_ingest_enabled", o.ingest === false ? "false" : "true");
  await m.setSetting("directory_sweep_enabled", o.sweep === false ? "false" : "true");
  if (o.legal !== false) { await m.setSetting("directory_storage_country", "Canada"); await m.setSetting("directory_steam_terms_reviewed_by", "Test Owner 2026-10-05"); }
