  assert.equal(r.probed, 3); assert.equal(r.alive, 2); assert.equal(r.failed, 1); assert.equal(r.blackout, false);
  assert.deepEqual([...new Set(sent.map((s) => s.host))].sort(), ["5.9.0.1", "5.9.0.2", "5.9.0.3"], "only eligible stored addresses");
  assert.ok(sent.every((s) => s.port === 2457), "the stored QUERY port is used");
  assert.ok(sent.every((s) => s.payload[4] === 0x54), "only A2S_INFO requests");
  const rows = await m.db.externalServer.findMany({ orderBy: { name: "asc" } });
  const by = (n: string) => rows.find((x) => x.name === n)!;
  assert.equal(by("Probe 0").probeStatus, "ALIVE"); assert.equal(by("Probe 0").players, 7); assert.equal(by("Probe 0").maxPlayers, 10);
  assert.ok(by("Probe 0").lastAliveAt && by("Probe 0").lastProbeAt);
  assert.equal(by("Probe 2").probeStatus, "UNKNOWN"); assert.equal(by("Probe 2").consecutiveFails, 1);
  for (const n of ["Probe 3", "Probe 4", "Probe 5", "Probe 6"]) assert.equal(by(n).lastProbeAt, null, `${n} was never probed`);
  // Within the retry window nothing is due; after it the failing row is retried; 3 failures in a row = DEAD.
  assert.equal((await m.directoryProbeTick({ ...base, now: NOW + 60_000, envOk: true })).probed, 0);
  await m.directoryProbeTick({ ...base, now: NOW + 11 * 60_000, envOk: true });
  assert.equal((await m.db.externalServer.findFirstOrThrow({ where: { name: "Probe 2" } })).consecutiveFails, 2);
  const r3 = await m.directoryProbeTick({ ...base, now: NOW + 22 * 60_000, envOk: true });
  const dead = await m.db.externalServer.findFirstOrThrow({ where: { name: "Probe 2" } });
  assert.equal(dead.probeStatus, "DEAD"); assert.equal(r3.newlyDead, 1);
  // The admin page's numbers are stored.
  const src = await m.db.directorySource.findUniqueOrThrow({ where: { key: "probe" } });
  assert.ok(src.lastRunAt && (src.stats as { probed: number }).probed >= 0 && !src.runningUntil);
});

T("prober: a tick where nothing answers is a blackout (our network), so no row changes", async () => {
  const m = await mods(); await reset(m);
  await m.setSetting("directory_ingest_enabled", "true"); await m.setSetting("directory_probe_enabled", "true");
  await m.db.externalServer.createMany({ data: Array.from({ length: 25 }, (_, i) => seedProbe(i + 10, { probeStatus: "ALIVE", lastAliveAt: new Date(NOW - 3600_000), lastProbeAt: new Date(NOW - 3600_000) })) });
  const rep = await m.directoryProbeTick({ now: NOW, envOk: true, transport: async () => null, ratePerSec: 100000, sleep: async () => {}, budgetMs: 20_000 });
  assert.equal(rep.probed, 25); assert.equal(rep.blackout, true);
  const rows = await m.db.externalServer.findMany();
  assert.ok(rows.every((r) => r.probeStatus === "ALIVE" && r.consecutiveFails === 0), "nobody was marked failed");
  const src = await m.db.directorySource.findUniqueOrThrow({ where: { key: "probe" } });
  assert.match(src.lastError ?? "", /Blackout/);
});

T("public pages: external rows need external_show; dead/blocked/hidden rows never show; with the prober on only answered rows show; counts go stale", async () => {
  const m = await mods(); await reset(m);
  const fresh = new Date(), stale = new Date(Date.now() - 5 * 3600_000);
  await m.db.externalServer.createMany({ data: [
    seedProbe(0, { name: "Alive fresh", probeStatus: "ALIVE", lastAliveAt: fresh, lastProbeAt: fresh, players: 5, maxPlayers: 10, lastSeenAt: fresh }),
    seedProbe(1, { name: "Alive stale counts", probeStatus: "ALIVE", lastAliveAt: stale, lastProbeAt: stale, players: 9, maxPlayers: 10, lastSeenAt: stale }),
    seedProbe(2, { name: "Dead one", probeStatus: "DEAD", consecutiveFails: 3, lastSeenAt: fresh }),
    seedProbe(3, { name: "Never checked", probeStatus: "UNKNOWN", lastSeenAt: fresh, players: 2, maxPlayers: 10 }),
    seedProbe(4, { name: "Blocked stored", blockedReason: "Another game host", blockedRule: "suffix:nitrado.net", probeStatus: "ALIVE", lastAliveAt: fresh, lastSeenAt: fresh }),
    seedProbe(5, { name: "Blocked live rule", host: "srv1.nitrado.net", probeStatus: "ALIVE", lastAliveAt: fresh, lastSeenAt: fresh }),
    seedProbe(6, { name: "Hidden by staff", hidden: true, probeStatus: "ALIVE", lastAliveAt: fresh, lastSeenAt: fresh }),
  ] });
  const names = async () => (await m.loadDirectory({ game: "valheim" })).entries.map((e) => e.name).sort();
  assert.deepEqual(await names(), [], "directory_external_show is off by default");
  await m.setSetting("directory_external_show", "true");
  assert.deepEqual(await names(), ["Alive fresh", "Alive stale counts", "Never checked"], "prober off: Steam list alone decides, dead/blocked/hidden never show");
  await m.setSetting("directory_probe_enabled", "true");
  assert.deepEqual(await names(), ["Alive fresh", "Alive stale counts"], "prober on: unchecked rows are not shown as live");
  const es = (await m.loadDirectory({ game: "valheim" })).entries;
  const f = es.find((e) => e.name === "Alive fresh")!, s = es.find((e) => e.name === "Alive stale counts")!;
  assert.equal(f.players, 5); assert.ok(f.checkedAt && f.attribution === "steam");
  assert.equal(s.players, null, "a count older than an hour is not shown as live"); assert.equal(s.maxPlayers, 10);
  // The marketing card carries the freshness line and the page gets the Valve attribution.
  const page = await import("../app/nxm/_data/server-directory");
  assert.match(page.card(f), /<time class="dr-chk" datetime="[^"]+" data-kind="Checked">Checked \d{4}-\d\d-\d\d \d\d:\d\d UTC<\/time>/);
  assert.match(page.attributionFor(es), /data-attrib="steam"/);
  assert.equal(page.attributionFor(es.filter((e) => e.nxeon)), "", "no Steam data on the page, no Steam attribution");
});
